  async function sendDocument(event: FormEvent<HTMLFormElement>, document: EventDeskDocument) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    setBusy(true); setError("");
    try {
      await send(`/api/eventdesk/documents/${document.id}/send`, departmentId, csrfToken, "POST", { recipientEmail: String(form.get("recipientEmail") ?? "").trim(), subject: String(form.get("subject") ?? "").trim(), message: String(form.get("message") ?? "").trim(), purpose: String(form.get("purpose") ?? "document") });
      await load();
      setReminderMode(false);
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "EventDesk could not send the document.";
      await load();
      setError(message);
    } finally { setBusy(false); }
  }

  async function downloadDocumentPdf(document: EventDeskDocument) {
    await action(async () => {
      const response = await fetch(`/api/eventdesk/documents/${document.id}/pdf`, { headers: { "x-department-id": departmentId } });
      if (!response.ok) { const result = await response.json() as { error?: string }; throw new Error(result.error || "Could not download this PDF."); }
      const url = URL.createObjectURL(await response.blob());
      const link = window.document.createElement("a"); link.href = url; link.download = `${document.number}.pdf`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    });
  }

