  async function exportAccountingCsv() {
    await action(async () => {
      const query = new URLSearchParams({ from: exportFrom, to: exportTo });
      const response = await fetch(`/api/eventdesk/finance/export?${query}`, { headers: { "x-department-id": departmentId } });
      if (!response.ok) {
        const result = await response.json().catch(() => ({})) as { error?: string };
        throw new Error(result.error || "The accounting export could not be downloaded.");
      }
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const link = window.document.createElement("a");
      link.href = url;
      link.download = `eventdesk-accounting-${exportFrom}-${exportTo}.csv`;
      link.click();
      URL.revokeObjectURL(url);
    });
  }

